const body = $('Webhook').first().json.body || {};
const date = String(body.date || '').trim();      // YYYY-MM-DD
const guests = parseInt(body.guests, 10);

const DURATION = 90;       // minutes per booking
const MAX_GUESTS = 8;
const MAX_DAYS_AHEAD = 30;
const STEP = 30;

const toMin = (s) => {
  const m = String(s || '').trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (!m) return null;
  let h = +m[1];
  const ap = m[3] && m[3].toUpperCase();
  if (ap === 'PM' && h < 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return h * 60 + +m[2];
};
const to24 = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const label = (m) => {
  const h = Math.floor(m / 60), mm = m % 60;
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return h12 + ':' + String(mm).padStart(2, '0') + ' ' + (h >= 12 ? 'PM' : 'AM');
};
const reply = (obj) => [{ json: obj }];

// ---- Validation ----
const t = toMin(body.time);
if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || t === null || !Number.isInteger(guests) || guests < 1) {
  return reply({ available: false, message: 'I need a valid date, time and number of guests to check availability.' });
}
const today = $now.toFormat('yyyy-MM-dd');
const lastDay = $now.plus({ days: MAX_DAYS_AHEAD }).toFormat('yyyy-MM-dd');
if (date < today) return reply({ available: false, message: 'That date is in the past. Please choose a future date.' });
if (date > lastDay) return reply({ available: false, message: 'We take bookings up to 30 days ahead.' });
if (guests > MAX_GUESTS) return reply({ available: false, message: 'I can book up to 8 guests. For larger groups, please call the restaurant.' });

// ---- Opening hours (Sun 13-21, Mon-Thu 12-22, Fri-Sat 12-23) ----
const dow = new Date(date + 'T12:00:00').getDay(); // 0 = Sunday
let open, close;
if (dow === 0) { open = 13 * 60; close = 21 * 60; }
else if (dow === 5 || dow === 6) { open = 12 * 60; close = 23 * 60; }
else { open = 12 * 60; close = 22 * 60; }
const lastStart = close - DURATION;
if (t < open || t > lastStart) {
  return reply({ available: false, message: `We take bookings between ${label(open)} and ${label(lastStart)} on that day.` });
}

// ---- Data (tables come from the "Get Tables" Airtable node) ----
const get = (j) => j.fields ?? j;
let tableItems = [], reservationItems = [];
let tablesError = null, reservationsError = null;
try { tableItems = $('Get Tables').all(); } catch (e) { tablesError = e.message; }
try { reservationItems = $('Get Reservations').all(); } catch (e) { reservationsError = e.message; }

const tables = tableItems.map(i => {
  const f = get(i.json);
  return { recordId: i.json.id, tableId: f['Table ID'], seats: Number(f['Seats']), area: f['Area'] };
}).filter(x => x.tableId && x.seats);

const booked = reservationItems.map(i => {
  const f = get(i.json);
  return { tables: f['Table'] || [], min: toMin(f['Time']) };
}).filter(r => r.min !== null);

const freeAt = (start) => {
  const busy = new Set();
  for (const r of booked) {
    if (Math.abs(r.min - start) < DURATION) r.tables.forEach(id => busy.add(id));
  }
  return tables.filter(x => x.seats >= guests && !busy.has(x.recordId))
               .sort((a, b) => a.seats - b.seats);
};

// ---- Requested slot ----
const free = freeAt(t);
if (free.length) {
  const pick = free[0]; // smallest table that fits
  return reply({
    available: true, date, time: to24(t), guests,
    table_id: pick.tableId, table_record_id: pick.recordId,
    seats: pick.seats, area: pick.area,
    message: `A table for ${guests} is available at ${label(t)}.`,
  });
}

// ---- Alternatives (nearest times, up to 3) ----
const alternatives = [];
for (let d = STEP; d <= 120 && alternatives.length < 3; d += STEP) {
  for (const s of [t - d, t + d]) {
    if (s >= open && s <= lastStart && alternatives.length < 3 && freeAt(s).length) {
      alternatives.push({ time: to24(s), label: label(s) });
    }
  }
}
return reply({
  available: false, date, time: to24(t), guests, alternatives,
  debug: {
    tables_found: tables.length,
    tables_big_enough: tables.filter(x => x.seats >= guests).length,
    bookings_that_day: booked.length,
    tables_error: tablesError,
    reservations_error: reservationsError,
  },
  message: alternatives.length
    ? `No table is free at ${label(t)}. Nearest available times: ${alternatives.map(a => a.label).join(', ')}.`
    : `No table is free around ${label(t)} on that date.`,
});
